class RunningProductCalculator {
  static List<int> runningProducts(List<int> input) {
    List<int> result = [];
    int product = 1;

    for (int i = 0; i < input.length; i++) {
      if (input[i] == 0) {
        product = 0;
      } else {
        product *= input[i];
      }
      result.add(product);
    }

    return result;
  }
}

void main() {
  // Test cases
  print(RunningProductCalculator.runningProducts([])); // Output: [0]
  print(
      RunningProductCalculator.runningProducts([1, 2, 3])); // Output: [1, 2, 6]
  print(
      RunningProductCalculator.runningProducts([0, 2, 3])); // Output: [0, 0, 0]
  print(RunningProductCalculator.runningProducts(
      [-1, 2, 3])); // Output: [-1, -2, -6]
  print(
      RunningProductCalculator.runningProducts([1, 0, 3])); // Output: [1, 0, 0]
}

List<int> runningProducts(List<int> input) =>
    RunningProductCalculator.runningProducts(input);

import 'package:aivexus_running_product/running_product.dart';
import 'package:test/test.dart';

void main() {
  test('independent contract, not model-authored', () {
    final d = <int>[2, -3, 4, 0, 9];
    if (runningProducts(d).toString() != '[2, -6, -24, 0, 0]')
      throw StateError('products');
    if (runningProducts(<int>[]).isNotEmpty) throw StateError('empty');
    if (runningProducts(<int>[-2, -2]).toString() != '[-2, 4]')
      throw StateError('negatives');
    if (d.length != 5) throw StateError('mutation');
    print(
        'PASS: independent Dart consumer for original model-generated running_product');
  });
}
